(25861, 'John 1:37', 'John', 1, 37, 'د یحیی دوو شاګردانو دا خبره واورېدله او عیسی پسې روان شول.', 'د یحیی دوو شاګردانو دا خبره واورېدله او عیسی پسې روان شول.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_1_37.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(25862, 'John 1:38', 'John', 1, 38, 'عیسی شاته وکتل او ویې لیدل چې هغوی هغه پسې روان دي نو پوښتنه یې ترې وکړه: «تاسو څه شي پسې ګرځئ؟» هغوی پوښتنه وکړه: «ربي ته چېرته اوسېږې؟» (د ربي معنی استاذ دی.)', 'عیسی شاته وکتل او ویې لیدل چې هغوی هغه پسې روان دی نو پوشتنه یې ترې وکره: «تاسو چه شی پسې ګرجی؟» هغوی پوشتنه وکره: «ربی ته چېرته اوسېزې؟» (د ربی معنی استاذ دی.)', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_1_38.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(25863, 'John 1:39', 'John', 1, 39, 'عیسی وویل: «راشئ او وګورئ.» دا شاوخوا د ماسپښین څلور بجې وې نو هغوی د هغه سره لاړل او ویې لیدل چې هغه چېرته اوسېده او پاتې ورځ یې د هغه سره تېره کړه.', 'عیسی وویل: «راشی او وګوری.» دا شاوخوا د ماسپشین چلور بجې وې نو هغوی د هغه سره لارل او ویې لیدل چې هغه چېرته اوسېده او پاتې ورج یې د هغه سره تېره کره.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_1_39.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237833, 1761237833),
(25864, 'John 1:40', 'John', 1, 40, 'د هغو دوه تنو څخه چې د یحیی د خبرو له اورېدلو وروسته عیسی پسې روان شو، یو یې د شمعون پطروس ورور اندریاس ؤ.', 'د هغو دوه تنو چخه چې د یحیی د خبرو له اورېدلو وروسته عیسی پسې روان شو، یو یې د شمعون پطروس ورور اندریاس و.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_1_40.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237833, 1761237833),
(25865, 'John 1:41', 'John', 1, 41, 'لومړنی کار چې هغه وکړ، هغه دا ؤ چې هغه خپل ورور شمعون پیدا کړ او هغه ته یې وویل: «مونږ مسیح موندلی دی،» چې د مسېح معنی ده وعده شوی پاچا.', 'لومرنی کار چې هغه وکر، هغه دا و چې هغه خپل ورور شمعون پیدا کر او هغه ته یې وویل: «مونز مسیح موندلی دی،» چې د مسېح معنی ده وعده شوی پاچا.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_1_41.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(25866, 'John 1:42', 'John', 1, 42, 'نو اندریاس شمعون عیسی ته راوست. عیسی هغه ته وکتل او ویې ویل: «ته د یوحنا زوی شمعون یې، خو له دې وروسته به ته د کیفا په نوم یادېږې.» (د کیفا معنی پطروس دی چې معنی یې تیږه ده.) عیسی فیلیپوس او نتناییل ته بلنه ورکوي', 'نو اندریاس شمعون عیسی ته راوست. عیسی هغه ته وکتل او ویې ویل: «ته د یوحنا زوی شمعون یې، خو له دې وروسته به ته د کیفا په نوم یادېزې.» (د کیفا معنی پطروس دی چې معنی یې تیزه ده.) عیسی فیلیپوس او نتناییل ته بلنه ورکوی', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_1_42.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(25867, 'John 1:43', 'John', 1, 43, 'بله ورځ عیسی دا پرېکړه وکړه چې جلیل ته لاړ شي. په لاره کې هغه فیلیپوس پیدا کړ او ورته یې وویل: «ما پسې راځه.»', 'بله ورج عیسی دا پرېکره وکره چې جلیل ته لار شی. په لاره کې هغه فیلیپوس پیدا کر او ورته یې وویل: «ما پسې راجه.»', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_1_43.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(25868, 'John 1:44', 'John', 1, 44, 'فیلیپوس د اندریاس او پطروس په شان د بیت‌صیدا ؤ.', 'فیلیپوس د اندریاس او پطروس په شان د بیت‌صیدا و.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_1_44.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(25869, 'John 1:45', 'John', 1, 45, 'فیلیپوس نتناییل راپیدا کړ او ورته ویې ویل: «مونږ هغه کس پیدا کړ چې موسی د شریعت په کتاب کې لیکلي او همدارنګه پیغمبرانو هم د هغه په هکله لیکنې کړي دي. هغه عیسی دی چې د ناصرې د ښار څخه دی او د یوسف زوی دی.»', 'فیلیپوس نتناییل راپیدا کر او ورته ویې ویل: «مونز هغه کس پیدا کر چې موسی د شریعت په کتاب کې لیکلی او همدارنګه پیغمبرانو هم د هغه په هکله لیکنې کری دی. هغه عیسی دی چې د ناصرې د شار چخه دی او د یوسف زوی دی.»', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_1_45.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
